function validate([words, x]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 50) return 'words needs 1 to 50 strings.';
  if (words.some(w => typeof w !== 'string' || w.length < 1 || w.length > 50)) return 'Each word has 1 to 50 characters.';
  if (words.some(w => !/^[a-z]+$/.test(w))) return 'Words use only lowercase English letters.';
  if (typeof x !== 'string' || !/^[a-z]$/.test(x)) return 'x is a single lowercase letter.';
  return null;
}

