function findWordsContaining(words, x) {
  const result = [];
  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    for (const ch of word) {
      if (ch === x) {
        result.push(i);
        break;
      }
    }
  }
  return result;
}

