function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = size === 'large' ? 4 + Math.floor(rand() * 23) : 1 + Math.floor(rand() * 4);
  const count = size === 'large' ? 50 : 1 + Math.floor(rand() * 6);
  const maxLength = size === 'large' ? 50 : 5;
  const words = [];
  for (let i = 0; i < count; i++) {
    const length = 1 + Math.floor(rand() * maxLength);
    let word = '';
    for (let j = 0; j < length; j++) word += letters[Math.floor(rand() * alphabet)];
    words.push(word);
  }
  const x = letters[Math.floor(rand() * (alphabet + 1))];
  return [words, x];
}
